style.css:
@-moz-document domain("pinterest.com") {
/* Force Cheri Liney everywhere */
    * {
        font-family: "Cheri Liney", cursive !important;
        color: #F2C1D1 !important;
    }

    /* Icons */
    svg,
    svg *,
    path,
    circle,
    rect,
    polygon {
        fill: #F2C1D1 !important;
        stroke: #F2C1D1 !important;
    }

    /* Make sure buttons + UI elements obey font */
    button,
    a,
    input,
    textarea,
    [role="button"],
    [role="link"],
    nav,
    header,
    div,
    span {
        font-family: "Cheri Liney", cursive !important;
    }
}
